import{z as n,x as B,o as r,c as l,q as E,j as o,D as e,d as s,s as i,S as A}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"hypervisor 的类型","description":"","frontmatter":{"title":"hypervisor 的类型","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/virt-hypervisor-types.md","filePath":"cs/virt-hypervisor-types.md","lastUpdated":1791413859000}'),p={name:"cs/virt-hypervisor-types.md"};function d(h,a,M,V,c,m){const t=B("Mermaid");return r(),l("div",null,[a[2]||(a[2]=E('<h1 id="hypervisor-的类型" tabindex="-1">hypervisor 的类型 <a class="header-anchor" href="#hypervisor-的类型" aria-label="Permalink to &quot;hypervisor 的类型&quot;">​</a></h1><div class="epigraph"><p>类型 1 与类型 2 说的是 VMM 活在哪一层、复用了谁的驱动与调度器；真正决定一台虚拟机行为的，是敏感指令那次陷入用什么机制接住。</p><footer>—— 据 Popek and Goldberg, Formal Requirements for Virtualizable Third Generation Architectures, 1974 整理</footer></div><p><a href="/cs/st-map">上一课</a>给「存储系统深入」收束：放大账、合同账、层次账三张账并读，顺序化是贯穿 LSM、LFS、FTL 与列存的第一母题，局部性是唯一的免费午餐——成本都在写入端明码标价。存储的账本合上，多租户的隔离问题换到下一层舞台。本课是「虚拟化与容器深入」的第一课。主干课里<a href="/cs/hypervisor-types">虚拟化类型 1 / 2</a>已经给过分类标签，<a href="/cs/trap-and-emulate">陷阱与模拟</a>也演示过一次陷入；本课把这些钉成一套机制语言：什么架构才可虚拟化、不可虚拟化时工程上有哪几条出路，后课的 KVM、微 VM 与容器都默认这套语言。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一个 VMM 要成立，得同时满足三件事：等价性（客户程序除时序外看不出自己在虚拟机里）、控制性（VMM 掌握物理资源，客户不能绕过）、效率（无须 VMM 介入的指令原地执行）。Popek 与 Goldberg 在 1974 年给出判定：当且仅当<strong>敏感指令是特权指令的子集</strong>，纯软件的陷落式 VMM 才可能。敏感指令是「结果依赖特权态」的指令，特权指令是「非特权态执行就陷入」的指令；前者被后者覆盖，硬件才替你把每一处越权变成一次陷入。这个判定解释了 VMM 的实现谱系，而不是给产品排座次。</p><p><span class="marginnote">术语翻译：特权指令是「在用户态一执行就报官」的指令，敏感指令是「结果随你在哪个特权级而变」的指令。Popek 与 Goldberg 的判定一句话说完——每种敏感指令都得报官，纯软件的 VMM 才兜得住；有指令能悄悄变行为，VMM 就瞎了。</span></p><p>缺口在真实 ISA 上：二十世纪七十年代的 x86 有十多条指令敏感却无特权——用户态执行不陷入、但行为随特权态改变（改标志位、读描述符表位置一类）。VMM 看不见这些操作，等价性与控制性同时失守。缺口不是「x86 慢」，是 x86 当时<strong>原则上不可虚拟化</strong>。</p><p><span class="marginnote">数字实例：当年 x86 有十多条「敏感却非特权」的指令，比如用户态改标志位、读段描述符表位置这类——执行了、没陷入、VMM 又看不见结果变了什么；等价性与控制性各漏一个口子，这是结构性的洞，不是调优能补的。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工程史的回答是三条出路，按「改哪一层」区分。</p><h3 id="三条出路" tabindex="-1">三条出路 <a class="header-anchor" href="#三条出路" aria-label="Permalink to &quot;三条出路&quot;">​</a></h3><p>第一，陷入后补洞：不行的指令靠动态二进制翻译，在客户代码执行前扫描替换。第二，改客机：Xen 在 2003 年干脆承认客内核要改写，把敏感操作换成对 hypervisor 的显式调用——半虚拟化，用兼容性换清晰。第三，改硬件：VT-x 与 AMD-V 给 ISA 补上「非根模式」，敏感指令真的会陷入，Popek-Goldberg 条件由硬件满足。今天的主流是第三条加第二条的混合，第一条例外存在于旧产品与特殊调试。</p>',12)),(r(),o(A,null,{default:e(()=>[i(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ARCH%5B%22ISA%20%E5%8F%AF%E8%99%9A%E6%8B%9F%E5%8C%96%3F%22%5D%20--%3E%7C%22%E6%98%AF%22%7C%20TE%5B%22%E7%BA%AF%E9%99%B7%E8%90%BD%E5%BC%8F%20VMM%22%5D%0A%20%20ARCH%20--%3E%7C%22%E5%90%A6%22%7C%20Q%5B%22%E9%80%89%E6%8B%A9%E5%87%BA%E8%B7%AF%22%5D%0A%20%20Q%20--%3E%20BT%5B%22%E4%BA%8C%E8%BF%9B%E5%88%B6%E7%BF%BB%E8%AF%91%22%5D%0A%20%20Q%20--%3E%20PV%5B%22%E6%94%B9%E5%AE%A2%E5%86%85%E6%A0%B8%3A%20%E5%8D%8A%E8%99%9A%E6%8B%9F%E5%8C%96%22%5D%0A%20%20Q%20--%3E%20HW%5B%22%E6%94%B9%20ISA%3A%20%E7%A1%AC%E4%BB%B6%E8%BE%85%E5%8A%A9%22%5D%0A%20%20BT%20--%3E%20MOD%5B%22%E7%8E%B0%E4%BB%A3%20VMM%20%E5%A4%9A%E4%B8%BA%E6%B7%B7%E5%90%88%22%5D%0A%20%20PV%20--%3E%20MOD%0A%20%20HW%20--%3E%20MOD%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>类型 1 与类型 2 度量的是<strong>复用边界</strong>：VMM 直接调度硬件并自带驱动（类型 1，如 Xen、ESXi），还是作为宿主 OS 的进程、复用宿主的驱动栈与调度器（类型 2，如托管式桌面产品）。KVM 落在中间：Linux 内核就是 VMM，vCPU 是可被 <a href="/cs/cgroup-cpu-sched">CFS</a> 调度的普通线程——这不是「1.5 类」的含混，而是复用边界的彻底外移：调度、内存、驱动全部沿用宿主，内核只补陷入机制。</p><p>半虚拟化与硬件辅助并不互斥。Xen 时代的方案如今常写成「硬件负责陷入，半虚拟化负责接口」：客机通过 <a href="/cs/virtio">virtio</a> 一类约定接口提交 I/O（后课细拆），硬件只接住剩余的敏感指令。判定的历史价值在于方向：<strong>每一代虚拟化技术都是在补「敏感指令无处陷入」这一具体缺口</strong>，而不是抽象的性能竞赛。</p>',3)),(r(),o(A,null,{default:e(()=>[i(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20VCPU%5B%22vCPU%20%E7%BA%BF%E7%A8%8B%22%5D%20--%3E%7C%22%E8%A2%AB%E8%B0%81%E8%B0%83%E5%BA%A6%22%7C%20CFS%5B%22%E5%AE%BF%E4%B8%BB%E5%86%85%E6%A0%B8%E8%B0%83%E5%BA%A6%E5%99%A8%22%5D%0A%20%20VCPU%20--%3E%7C%22%E9%99%B7%E5%85%A5%E8%B0%81%E6%8E%A5%22%7C%20VMX%5B%22%E5%86%85%E6%A0%B8%E5%86%85%20VMX%20%E6%8E%A5%E4%BD%8F%E6%95%8F%E6%84%9F%E6%8C%87%E4%BB%A4%22%5D%0A%20%20VCPU%20--%3E%7C%22I%2FO%20%E8%B5%B0%E4%BB%80%E4%B9%88%22%7C%20VIRTIOQ%5B%22virtio%20%E5%8D%8A%E8%99%9A%E6%8B%9F%E5%8C%96%E6%8E%A5%E5%8F%A3%22%5D%0A%20%20VIRTIOQ%20--%3E%20QEMU%5B%22QEMU%20%E6%88%96%20vhost%20%E5%90%8E%E7%AB%AF%22%5D%0A%20%20DRV%5B%22%E8%AE%BE%E5%A4%87%E9%A9%B1%E5%8A%A8%22%5D%20--%3E%20HOSTK%5B%22%E5%85%A8%E9%83%A8%E6%B2%BF%E7%94%A8%E5%AE%BF%E4%B8%BB%E5%86%85%E6%A0%B8%22%5D%0A%20%20CFS%20--%3E%20HOSTK%0A%20%20VMX%20--%3E%20HOSTK%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<p><span class="marginnote">KVM 的直觉类比：它不是在内核里另盖一栋调度楼，而是在原有大楼里加了一层门禁——排队进门（调度）、找水电工（驱动）、物业账目（内存）全用宿主原班人马；门禁只干一件事，客户越权时把人拦下并记一笔，其余照旧。</span></p><p><span class="marginnote">把「类型 2 一定更不安全或更慢」当结论是常见误读。托管式 VMM 复用宿主驱动省去重写，宿主被攻陷时客户才连带失守；裸机型则要自己维护特权分区（Xen 的 Dom0）——两边交换的是不同的运维债，不是一条单向光谱。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不展开 VMX 的字段与退出码，那是下一课 KVM/QEMU 与 <a href="/cs/vmx-vmexit">VMX 与 VM exit</a> 的对象；也不给容器留位置——容器根本不引入第二套特权级视图，它与本课的对照要到「安全边界」「性能开销」两课才有量化意义。嵌套虚拟化（VMM 之下再套 VMM）在本课只承认存在，机制归<a href="/cs/nested-virtualization">嵌套虚拟化</a>。</p><p>判定本身也有边界：Popek-Goldberg 说的是<strong>递归虚拟化的充分条件</strong>（对第三代体系结构陈述），不是性能上限，也不覆盖共享内存多核上的新问题——同一地址被两个客户核缓存的观感差异，陷入机制管不住，后课测开销时会回来。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可虚拟化的判定是「敏感指令 ⊆ 特权指令」：陷入必须覆盖所有观察特权态的指令。</li><li>x86 曾不满足判定；二进制翻译、半虚拟化、硬件辅助是三条补法，现代 VMM 是混合体。</li><li>类型 1/2 说的是复用边界（驱动、调度器归谁），不是安全或性能的单向排序。</li><li>KVM 把复用边界推到宿主内核：vCPU 是普通线程，内核只补陷入。</li><li>出处：Popek and Goldberg 1974；Barham et al., Xen, SOSP 2003；据对该时代 x86 指令行为的分析整理。</li></ul>',7))])}const u=n(p,[["render",d]]);export{C as __pageData,u as default};
